refentry.refsect1:
&reftitle.description;

 public mixedYaf_Config_Simple::current


Retorna o valor da entrada de configuração atual durante a iteração. Valores de array são encapsulados em um objeto Yaf_Config_Abstract.

  &reftitle.examples;

   Exemplo de Yaf_Config_Simple::current


<?php
$config = new Yaf_Config_Simple([
    'application' => ['name' => 'MyApp'],
    'version'     => '1.0',
]);

$config->rewind();
while ($config->valid()) {
    $value = $config->current();
    if ($value instanceof Yaf_Config_Abstract) {
        echo $config->key(), " => <config node>\n";
    } else {
        echo $config->key(), " => ", $value, "\n";
    }
    $config->next();
}
?>


   &example.outputs.similar;


application => <config node>
version => 1.0
